package com.civic.controller; import com.civic.dto.ActivityResponse; import com.civic.entity.*; import com.civic.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/petitions") @RequiredArgsConstructor public class PetitionActivityController {private final PetitionRepository petitions;private final PetitionActivityRepository activities;private final PetitionResponseLogRepository responses;
 @GetMapping("/{id}/timeline") public Map<String,Object> timeline(@PathVariable Long id){Petition p=petitions.findById(id).orElseThrow(()->new RuntimeException("Petition not found"));List<ActivityResponse> a=activities.findByPetitionOrderByCreatedAtAsc(p).stream().map(x->ActivityResponse.builder().id(x.getId()).action(x.getAction()).description(x.getDescription()).officialName(x.getOfficial()==null?null:x.getOfficial().getName()).designation(x.getOfficial()==null?null:x.getOfficial().getDesignation()).department(x.getOfficial()==null?null:x.getOfficial().getDepartment()).createdAt(x.getCreatedAt()).build()).toList();return Map.of("activities",a,"responses",responses.findByPetitionOrderByCreatedAtAsc(p).stream().map(x->Map.of("id",x.getId(),"comment",x.getComment()==null?"":x.getComment(),"status",x.getStatus()==null?null:x.getStatus().name(),"officialName",x.getOfficial().getName(),"createdAt",x.getCreatedAt())).toList());}
}
